window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[53]={"id":"053","numero":53,"titre":"Croissance normale et pathologique","objectifs":[{"id":"53-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la croissance normale de l’enfant","contenu":"<p>La <span class=\"kw-def\">croissance</span> est le <strong>reflet de la santé de l’enfant</strong> : son évaluation systématique est un élément clé du <span class=\"kw-def\">suivi</span> pédiatrique. Elle se fait au niveau de la <span class=\"kw-clinique\">plaque de croissance</span> et résulte d’une intégration de facteurs <strong>nutritionnels, psychoaffectifs, osseux, génétiques</strong> (taille cible) et <strong>hormonaux</strong> (GH, IGF-1, hormones thyroïdiennes, hormones sexuelles).</p>\n\n      <div class=\"callout callout-info\">\n        <strong>⭐ Par cœur — repères clés à connaître.</strong>\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Âge</th><th>Taille (cm)</th><th>Poids (kg)</th><th>PC (cm)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Naissance à terme</strong></td>\n            <td>TN = <span class=\"kw-chiffre\">50</span></td>\n            <td>PN = <span class=\"kw-chiffre\">3,5</span></td>\n            <td>PCN = <span class=\"kw-chiffre\">35</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">4 mois</span></strong></td>\n            <td>60 <em>(+<span class=\"kw-chiffre\"> 10 cm</span> depuis la naissance)</em></td>\n            <td>7 <em>(PN × 2)</em></td>\n            <td>PC = (Taille ÷ 2) + 10 = <span class=\"kw-chiffre\">40</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">9 mois</span></strong></td>\n            <td>70 <em>(+<span class=\"kw-chiffre\"> 20 cm</span> depuis la naissance)</em></td>\n            <td>9</td>\n            <td>PC = (Taille ÷ 2) + 10 = <span class=\"kw-chiffre\">45</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">1 an</span></strong></td>\n            <td>75 <em>(+<span class=\"kw-chiffre\"> 25 cm</span> depuis la naissance)</em></td>\n            <td>10 <em>(PN × 3)</em></td>\n            <td>PC = (Taille ÷ 2) + 10 = <span class=\"kw-chiffre\">47,5</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">4 ans</span></strong></td>\n            <td>100 <em>(≈ TN × 2, soit environ 1 mètre)</em></td>\n            <td>16</td>\n            <td><span class=\"kw-chiffre\">50</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li><strong>Taille</strong> : <span class=\"kw-chiffre\">+25 cm la 1ʳᵉ année</span>, puis <span class=\"kw-chiffre\">+10 cm/an entre 2 et 3 ans</span></li>\n        <li><strong>Poids</strong> : <span class=\"kw-chiffre\">+25 g/j</span> au 1ᵉʳ trimestre</li>\n        <li>Chez le <span class=\"kw-clinique\">prématuré</span> : mensurations interprétées en fonction de l’<strong>âge gestationnel</strong> selon des courbes de référence</li>\n      </ul>\n\n      <h4><span class=\"kw-clinique\">Les</span> 4 phases de la croissance staturale</h4>\n\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Caractéristiques</th><th>Repères chiffrés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Croissance fœtale</strong></td>\n            <td>Reflétée par <span class=\"kw-clinique\">les</span> paramètres de naissance ; <span class=\"kw-chiffre\">phase la plus rapide</span></td>\n            <td>Taille à la naissance : <strong><span class=\"kw-chiffre\">50 cm</span> en <span class=\"kw-chiffre\">9 mois</span></strong> (TN)</td>\n          </tr>\n          <tr>\n            <td><strong>Naissance →<span class=\"kw-chiffre\"> 4 ans</span></strong></td>\n            <td>Vitesse élevée qui décroît progressivement, avec mise sur le <span class=\"kw-clinique\">couloir de croissance génétique</span> (reflété par la <strong>taille cible</strong>)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-chiffre\">1 an</span> : <strong>+<span class=\"kw-chiffre\">25 cm</span></strong> (<span class=\"kw-chiffre\">75 cm</span>)</li>\n                <li><span class=\"kw-chiffre\">2-3 ans</span> : <strong>+<span class=\"kw-chiffre\">10 cm</span>/an</strong></li>\n                <li><span class=\"kw-chiffre\">4 ans</span> : <strong><span class=\"kw-chiffre\">100 cm</span></strong> (2 × TN)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">4 ans</span> → début puberté</strong></td>\n            <td>Phase de croissance <span class=\"kw-clinique\">linéaire</span></td>\n            <td>\n              <ul>\n                <li>Vitesse : <strong><span class=\"kw-chiffre\">5-6 cm</span>/an</strong></li>\n                <li><span class=\"kw-alerte\">Seuil pathologique : &lt; 4 cm/an après 4 ans</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Puberté</strong></td>\n            <td>Accélération de la vitesse (pic de croissance pubertaire)</td>\n            <td>\n              <ul>\n                <li>Fille : <strong>+<span class=\"kw-chiffre\">20-25 cm</span></strong></li>\n                <li>Garçon : <strong>+<span class=\"kw-chiffre\">25-30 cm</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Taille adulte moyenne</strong> (courbes françaises 2018) : <span class=\"kw-chiffre\">177 cm</span> chez l’homme · <span class=\"kw-chiffre\">165 cm</span> chez la femme.\n      </div>\n\n      <h4>Évaluation pratique de la croissance</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mesures</strong></td>\n            <td>\n              <ul>\n                <li>Évaluation de base : <span class=\"kw-clinique\">poids</span> + <span class=\"kw-clinique\">taille</span></li>\n                <li>Jusqu’à <strong><span class=\"kw-chiffre\">3 ans</span></strong> : ajouter la mesure du <span class=\"kw-clinique\">périmètre crânien (PC)</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fréquence</strong><br><em>(à noter dans le carnet de santé)</em></td>\n            <td>\n              <ul>\n                <li>Naissance →<span class=\"kw-chiffre\"> 2 ans</span> : <strong>au minimum tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span></strong></li>\n                <li><span class=\"kw-chiffre\">2 ans</span> → fin de croissance : <strong>tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Analyse systématique d’une courbe : 5 informations</h4>\n\n      <table >\n        <thead>\n          <tr><th>Information</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Naissance</strong></td>\n            <td>Reflet de la <span class=\"kw-clinique\">croissance fœtale</span> — mensurations à la naissance</td>\n          </tr>\n          <tr>\n            <td><strong>Âge / Genre</strong></td>\n            <td>Courbes adaptées à la population :<span class=\"kw-chiffre\"> 95 %</span> des enfants situés entre <span class=\"kw-chiffre\">– 2 DS</span> (2,5ᵉ percentile) et <span class=\"kw-chiffre\">+ 2 DS</span> (97,5ᵉ percentile)</td>\n          </tr>\n          <tr>\n            <td><strong>Potentiel <span class=\"kw-etio\">génétique</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Taille cible</span> = moyenne des tailles parentales <strong>±<span class=\"kw-chiffre\"> 6,5 cm</span></strong> (+ si garçon, – si fille)</li>\n                <li>Taille adulte de <span class=\"kw-chiffre\">95 %</span> des enfants : <strong>± 1,5 DS de la taille cible</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitesse</strong></td>\n            <td>Aspect de la courbe — reflet de la vitesse de croissance</td>\n          </tr>\n          <tr>\n            <td><strong>IMC</strong></td>\n            <td>Rapport statural/pondéral</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Valeurs pathologiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Seuils pathologiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Taille</strong></td>\n            <td>\n              <ul>\n                <li>Population générale : <span class=\"kw-alerte\">&lt; – 2 DS</span></li>\n                <li>Par rapport à la taille cible : <span class=\"kw-alerte\">&lt; – 1,5 DS</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitesse de croissance</strong></td>\n            <td>\n              <ul>\n                <li>Seuil : <span class=\"kw-alerte\">&lt; 4 cm/an après 4 ans</span></li>\n                <li><span class=\"kw-clinique\">Ralentissement régulier</span> → pathologie <strong>constitutionnelle</strong></li>\n                <li><span class=\"kw-alerte\">Cassure</span> → pathologie <strong><span class=\"kw-etio\">acquise</span></strong> (évoquer <span class=\"kw-alerte\">craniopharyngiome</span> en 1ᵉʳ lieu)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IMC bas</strong></td>\n            <td>Déficit pondéral précédant le retard statural → <span class=\"kw-clinique\">cause nutritionnelle</span> (ex. <span class=\"kw-etio\">maladie cœliaque</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>IMC élevé</strong></td>\n            <td>\n              <ul>\n                <li>Avec accélération de la vitesse → <strong><span class=\"kw-etio\">obésité</span> commune</strong></li>\n                <li><span class=\"kw-alerte\">Prise de poids + ralentissement statural</span> → évoquer :\n                  <ul>\n                    <li><strong><span class=\"kw-etio\">Génétique</span></strong> : <span class=\"kw-etio\">obésité</span> syndromique, maladie osseuse constitutionnelle</li>\n                    <li><strong>Hormonale</strong> : déficit en GH, <span class=\"kw-etio\">hypothyroïdie</span>, hypercorticisme</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"53-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","contenu":"<p>Le retard de croissance staturo-pondérale est défini par une <strong>anomalie de la taille</strong> et/ou un <strong>ralentissement de la vitesse de croissance</strong>. Il doit <span class=\"kw-alerte\">toujours</span> être considéré comme un <strong>signe d’appel</strong> justifiant une évaluation.</p>\n\n      <h4>Définition d’une anomalie de croissance staturale</h4>\n\n      <ul>\n        <li>Taille <span class=\"kw-alerte\">&lt; – 2 DS</span> selon <span class=\"kw-clinique\">les</span> courbes de la population générale</li>\n        <li>et/ou Taille <span class=\"kw-alerte\">&lt; – 1,5 DS</span> par rapport à la <span class=\"kw-def\">taille cible génétique</span></li>\n        <li>et/ou <strong>Ralentissement</strong> ou <span class=\"kw-alerte\">Cassure</span> de la vitesse de croissance (&lt;<span class=\"kw-chiffre\"> 4 cm</span>/an après <span class=\"kw-chiffre\">4 ans</span>)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ À retenir.</strong> Le retard staturo-pondéral est <strong>toujours un signe d’appel</strong> — il justifie systématiquement une évaluation, jamais une simple <span class=\"kw-def\">surveillance</span> d’attente.\n      </div>\n\n      <h4>Démarche en 2 situations cliniques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Orientation étiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Retard pondéral isolé ou antérieur au retard statural</strong></td>\n            <td>Déséquilibre de la balance énergétique :\n              <ul>\n                <li>Carence d’apports</li>\n                <li>Malabsorption</li>\n                <li>Augmentation des dépenses énergétiques</li>\n                <li>Pertes excessives</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Retard statural prédominant</strong><br><em>(poids en rapport avec la taille ou excessif)</em></td>\n            <td>\n              <ul>\n                <li>Origine <span class=\"kw-clinique\">énergétique</span></li>\n                <li>Origine <span class=\"kw-clinique\">endocrinienne</span> (<span class=\"kw-etio\">hypothyroïdie</span>, hypercorticisme, déficit en GH)</li>\n                <li>Origine <span class=\"kw-clinique\">osseuse</span> ou <span class=\"kw-clinique\">génétique</span> (toujours évoquer le <span class=\"kw-alerte\">syndrome de Turner</span> chez la fille → caryotype systématique)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Enquête clinique — interrogatoire systématique</h4>\n\n      <ul>\n        <li><strong>ATCD familiaux</strong> : consanguinité, arbre généalogique (poids, tailles, âges pubertaires des parents et de la fratrie)</li>\n        <li><strong>ATCD personnels</strong> : déroulement et terme de la <span class=\"kw-ci\">grossesse</span>, mensurations à la naissance, pathologie néonatale, acquisitions psychomotrices, alimentation, ATCD médico-chirurgicaux, traitements</li>\n        <li><strong>Contexte psychosocial</strong> et retentissement psychologique</li>\n        <li>En période pubertaire : <span class=\"kw-clinique\">classification de Tanner</span> des caractères sexuels secondaires</li>\n      </ul>\n\n      <h4>Signaux d’alerte à reconnaître d’emblée</h4>\n\n      <div class=\"callout callout-warn\">\n        <strong>🔥 <span class=\"kw-alerte\">Urgence</span> diagnostique</strong> — devant <span class=\"kw-alerte\">cassure de la vitesse de croissance</span> et/ou <span class=\"kw-alerte\">signes d’HTIC</span> :\n        <ul>\n          <li>Éliminer en 1ᵉʳ lieu une <strong>pathologie <span class=\"kw-etio\">tumorale</span> hypophysaire</strong> (<span class=\"kw-alerte\">craniopharyngiome</span>)</li>\n          <li>Examens en <span class=\"kw-alerte\">urgence</span> : <strong>imagerie cérébrale et hypophysaire (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>)</strong> + <strong>fond d’œil</strong></li>\n        </ul>\n      </div>\n\n      <ul>\n        <li><span class=\"kw-alerte\">Prise de poids + ralentissement statural</span> → évoquer pathologie hormonale (GHD, <span class=\"kw-etio\">hypothyroïdie</span>, hypercorticisme) ou <span class=\"kw-etio\">génétique</span> (<span class=\"kw-etio\">obésité</span> syndromique, maladie osseuse constitutionnelle)</li>\n        <li><span class=\"kw-chiffre\">Prise de poids isolée</span> sans ralentissement statural → <strong>ne pas évoquer</strong> de pathologie hormonale</li>\n        <li><strong>Petite taille disproportionnée</strong> → <span class=\"kw-etio\">maladie osseuse constitutionnelle</span> → radiographies squelettiques</li>\n        <li>Chez une <strong>fille</strong> avec retard statural → <span class=\"kw-alerte\">syndrome de Turner</span> à évoquer systématiquement → <strong>caryotype sanguin</strong></li>\n      </ul>","frequence":4},{"id":"53-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un retard pondéral isolé ou antérieur au retard statural","contenu":"<p>Un <span class=\"kw-def\">retard pondéral isolé</span> (ou précédant un retard statural) est indicatif d’un <strong>déséquilibre de la balance énergétique</strong>. La démarche cherche à identifier laquelle des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>randes causes est en jeu.</p>\n\n      <h4>Principales causes d’insuffisance pondérale</h4>\n\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Carence d’apports</strong></td>\n            <td>\n              <ul>\n                <li>Négligence, régimes carencés (<span class=\"kw-clinique\">végétalisme</span>)</li>\n                <li><span class=\"kw-clinique\">Anorexie</span> psychogène ou organique</li>\n                <li><span class=\"kw-clinique\">Vomissements</span>, troubles de l’oralité</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Malabsorption</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Maladie cœliaque</span></li>\n                <li><span class=\"kw-clinique\">MICI</span></li>\n                <li><span class=\"kw-clinique\">APLV</span> (<span class=\"kw-ci\">allergie</span> aux protéines du lait de vache)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Augmentation de la dépense énergétique</strong></td>\n            <td>\n              <ul>\n                <li>Maladies cardio-respiratoires : cardiopathie <span class=\"kw-etio\">congénitale</span>, <span class=\"kw-etio\">SAHOS</span>, <span class=\"kw-clinique\">dyspnée</span> obstructive, <span class=\"kw-ci\">insuffisance respiratoire</span></li>\n                <li>Maladies héréditaires du métabolisme</li>\n                <li>Maladies inflammatoires (maladies de système), immunitaires (<span class=\"kw-clinique\">déficit immunitaire</span>)</li>\n                <li><span class=\"kw-etio\">Hyperthyroïdie</span> : insuffisance pondérale associée à une <strong>avance staturale</strong> <em>(effet direct des hormones thyroïdiennes sur la <span class=\"kw-clinique\">plaque</span> de croissance)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pertes excessives</strong></td>\n            <td>\n              <ul>\n                <li><strong>Digestives</strong> : diarrhées chroniques, pertes par stomies ou aspirations</li>\n                <li><strong>Urinaires</strong> : <span class=\"kw-etio\">diabète</span> sucré, <span class=\"kw-etio\">diabète</span> insipide, néphropathie</li>\n                <li><strong>Cutanées</strong> : brûlure étendue, <span class=\"kw-clinique\">eczéma</span> sévère, épidermolyse bulleuse</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège fréquent.</strong> Une <span class=\"kw-alerte\">insuffisance pondérale + avance staturale</span> oriente vers une <strong><span class=\"kw-etio\">hyperthyroïdie</span></strong> — c’est la signature paradoxale à connaître.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 274 — <span class=\"kw-clinique\">Vomissements</span> du nourrisson, de l’enfant et de l’adulte · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique chez l’enfant et chez l’adulte · 253 — <span class=\"kw-etio\">Obésité</span> de l’enfant et de l’adulte</em></p>","frequence":2},{"id":"53-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un retard statural prédominant","contenu":"<p>Le <span class=\"kw-def\">retard statural prédominant</span> (poids en rapport avec la taille ou excessif) oriente vers des causes essentiellement énergétiques, endocriniennes, osseuses ou génétiques. La démarche associe une <strong>enquête paraclinique</strong> structurée et un raisonnement étiologique.</p>\n\n      <h4>Enquête paraclinique devant un retard statural prédominant</h4>\n\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Examens</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Selon l’orientation clinique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Poids excessif</span> en regard de la taille : <strong><span class=\"kw-bio\">TSH</span>-<span class=\"kw-bio\">T4L</span>, IGF-1, cortisolurie des <span class=\"kw-chiffre\">24 h</span></strong></li>\n                <li><span class=\"kw-clinique\">Disproportion corporelle</span> : <strong>RX osseuses</strong></li>\n                <li><span class=\"kw-clinique\">Dysmorphie, malformations, retard mental</span> : <strong>avis <span class=\"kw-etio\">génétique</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bilan général en l’absence d’orientation</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Biologique</span> standard : <span class=\"kw-bio\">NFS, ionogramme sanguin, créatinine, bilan hépatique, VS, CRP</span></li>\n                <li>Recherche de carence : <span class=\"kw-bio\">calcémie, phosphatémie, réserve alcaline, ferritine</span></li>\n                <li>Bilan endocrinien : <span class=\"kw-bio\">TSH-T4L, IGF-1</span></li>\n                <li>Cœliaque : <span class=\"kw-bio\">IgA anti-transglutaminase + IgA totales</span></li>\n                <li><span class=\"kw-alerte\">Caryotype sanguin chez la fille</span> (Turner)</li>\n                <li><span class=\"kw-bio\">Bandelette urinaire</span> : <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">glycosurie</span>, densité urinaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>🔥 <span class=\"kw-alerte\">Urgence</span></strong></td>\n            <td>\n              <ul>\n                <li>Cassure de la vitesse staturale et/ou <span class=\"kw-alerte\">signes d’HTIC</span></li>\n                <li>Examens : <span class=\"kw-imagerie\">imagerie cérébrale et hypophysaire (TDM ou IRM)</span> + <span class=\"kw-clinique\">fond d’œil</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Principales causes de retard statural prédominant</h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Carence énergétique</strong></td>\n            <td>\n              <ul>\n                <li>Soit retard statural secondaire à une insuffisance pondérale (le plus souvent)</li>\n                <li>Soit anomalie de taille isolée, notamment dans certaines pathologies digestives (ex. <span class=\"kw-alerte\">maladie cœliaque</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Carence de soins</strong><br><em>(nanisme psychosocial)</em></td>\n            <td>\n              <ul>\n                <li><strong>Mécanisme</strong> : <span class=\"kw-etio\">carence de soins + négligence</span> → carence d’apports + déficit hormonal d’origine psychologique → retard</li>\n                <li><strong>Confirmation</strong> : amélioration de la croissance <span class=\"kw-alerte\">après éloignement de l’enfant de sa famille</span> (diagnostic a posteriori)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hormonales</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Déficit en GH</span> : <span class=\"kw-etio\">congénital</span> ou acquis, isolé ou associé à d’autres déficits hypophysaires <em>(toujours évoquer une tumeur hypophysaire — <strong>craniopharyngiome</strong>)</em></li>\n                <li><span class=\"kw-etio\">Hypothyroïdie</span> <span class=\"kw-etio\">congénitale</span> ou acquise (<span class=\"kw-etio\">thyroïdite</span> de <strong>Hashimoto</strong>++) : <span class=\"kw-chiffre\">excès de poids associé</span></li>\n                <li><span class=\"kw-etio\">Hypercorticisme</span> (<span class=\"kw-etio\">iatrogène</span> ++, plus rarement maladie de Cushing) : <span class=\"kw-chiffre\">excès de poids associé</span></li>\n                <li><strong>Retards pubertaires</strong> : <span class=\"kw-clinique\">absence d’accélération pubertaire de la vitesse de croissance</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Maladies osseuses constitutionnelles</span> : évoquées devant une <strong>petite taille disproportionnée</strong>\n                  <ul>\n                    <li>Suspecter si retard <strong>dysharmonieux</strong> prédominant sur <span class=\"kw-clinique\">les</span> membres ou le tronc</li>\n                    <li>Mesures : <span class=\"kw-clinique\">envergure ≈ taille</span> · <span class=\"kw-clinique\">taille assise ≈ ½ taille debout</span></li>\n                    <li>Confirmation : <span class=\"kw-imagerie\">RX de squelette</span> + <span class=\"kw-bio\">analyses génétiques ciblées</span></li>\n                  </ul>\n                </li>\n                <li><span class=\"kw-clinique\">RCIU</span> sans rattrapage statural postnatal</li>\n                <li><span class=\"kw-alerte\">Syndrome de Turner</span> chez la fille (ou autres anomalies chromosomiques / génétiques)</li>\n                <li><span class=\"kw-etio\">Petite taille idiopathique</span> : le plus souvent familiale — <strong>diagnostic d’élimination</strong> (~<span class=\"kw-chiffre\">85 %</span> des cas explorés)\n                  <ul>\n                    <li>Tailles parentales basses · vitesse de croissance <strong>régulière</strong></li>\n                    <li><span class=\"kw-clinique\">Âge osseux = âge chronologique (âge civil)</span> → discrimine du <strong>retard simple</strong> (où l’<span class=\"kw-clinique\">AO est retardé</span>)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus — Déficit en GH (GHD)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <ul>\n                <li>Retard de croissance : principale manifestation hors période néonatale</li>\n                <li><span class=\"kw-alerte\">Accidents hypoglycémiques</span> (déficits somatotrope et corticotrope) : fréquents et souvent révélateurs</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              <ul>\n                <li>Test de <span class=\"kw-def\">dépistage</span> : <span class=\"kw-bio\">dosage basal de l’IGF-1</span> (positif si abaissé, mais non spécifique)</li>\n                <li>Test de stimulation : <span class=\"kw-bio\">hypoglycémie insulinique</span> (positif si absence de réponse de la GH)</li>\n                <li>Recherche étiologique : <span class=\"kw-imagerie\">IRM centrée sur la région hypothalamo-hypophysaire</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>À ne pas faire ❌</strong></td>\n            <td><span class=\"kw-alerte\">Dosage ponctuel de GH</span> : aucun intérêt car sécrétion <strong>pulsatile</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Causes congénitales</strong><br><em>(malformation hypothalamo-hypophysaire)</em></td>\n            <td>\n              <ul>\n                <li><strong>À la naissance</strong> : hypoglycémies prolongées (&gt; 1ʳᵉ semaine de vie) ; mensurations le plus souvent <em>normales</em></li>\n                <li><strong>Ensuite</strong> : retard de croissance ne se manifestant que dans <span class=\"kw-clinique\">les</span> 1ᵉʳᵉˢ années</li>\n                <li><strong>Anomalies de la ligne médiane</strong> : colobome, sténose des sinus piriformes, anomalies du palais ou de la luette</li>\n                <li><strong>Déficits hypophysaires associés</strong> :\n                  <ul>\n                    <li><span class=\"kw-clinique\">Ictère</span> (déficit thyréotrope ou corticotrope)</li>\n                    <li><span class=\"kw-clinique\">Verge de petite taille</span> et/ou <span class=\"kw-clinique\">cryptorchidie</span> (déficit gonadotrope)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Causes acquises</strong></td>\n            <td>\n              <ul>\n                <li>Traumatisme crânien sévère, infections neuroméningées, <span class=\"kw-ttt\">radiothérapie</span> cérébrale</li>\n                <li><span class=\"kw-alerte\">Craniopharyngiome</span> à toujours évoquer :\n                  <ul>\n                    <li><span class=\"kw-alerte\">Cassure de la vitesse de croissance</span></li>\n                    <li><span class=\"kw-alerte\">HTIC</span>, signes neurologiques, déficits hormonaux associés, <span class=\"kw-etio\">diabète insipide</span> (souvent associé)</li>\n                    <li><span class=\"kw-clinique\">Œdème papillaire</span> (<span class=\"kw-alerte\">HTIC</span>), <span class=\"kw-clinique\">hémianopsie bitemporale</span> (compression du chiasma optique)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus — Retard simple de croissance et de puberté (diagnostic d’élimination)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td>Axe hypothalamo-hypophyso-gonadique non sorti de la quiescence ; activation gonadotrope retardée</td>\n          </tr>\n          <tr>\n            <td><strong>Sex-ratio</strong></td>\n            <td>Cause la plus fréquente de retard statural et pubertaire à l’adolescence chez <span class=\"kw-clinique\">les</span> garçons ; plus rare chez les filles</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Critères de</span> <span class=\"kw-def\">surveillance</span> simple</strong><br><em>(sans examens complémentaires)</em></td>\n            <td>\n              <ul>\n                <li>ATCD familiaux de puberté tardive (souvent retrouvés)</li>\n                <li>Absence d’ATCD de cryptorchidie bilatérale</li>\n                <li>Examen physique normal (pas de signes de tumeur intracrânienne ni de maladie chronique)</li>\n                <li>Infléchissement statural modéré/progressif (perte staturale <strong>&lt; 1 DS</strong>)</li>\n                <li>Taille dans <span class=\"kw-clinique\">les</span> limites de la normale (<strong>&gt; – 2 DS</strong>)</li>\n                <li>Âge osseux retardé : <strong>AO &lt;<span class=\"kw-chiffre\"> 11 ans</span></strong> chez la fille, <strong>&lt;<span class=\"kw-chiffre\"> 13 ans</span></strong> chez le garçon</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td><span class=\"kw-def\">Pronostic</span> bon (développement pubertaire et statural) — <span class=\"kw-def\">surveillance</span> jusqu’au démarrage pubertaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus — Petite taille de naissance (RCIU / PAG)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Contenu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>RCIU</strong></td>\n            <td>Réservé aux enfants ayant la <strong>preuve du début intra-utérin</strong> du retard (ex. <span class=\"kw-imagerie\">échographie</span> anténatale)</td>\n          </tr>\n          <tr>\n            <td><strong>PAG (SGA)</strong></td>\n            <td>\n              <ul>\n                <li>Poids <span class=\"kw-chiffre\">&lt; 10ᵉ percentile</span> pour l’âge gestationnel</li>\n                <li>PAG sévère : poids <span class=\"kw-chiffre\">&lt; 3ᵉ percentile</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li>Normalisation dans <span class=\"kw-clinique\">les</span> 2 premières années dans <strong><span class=\"kw-chiffre\">90 %</span></strong> des cas</li>\n                <li>Pas de rattrapage dans <strong><span class=\"kw-chiffre\">10-15 %</span></strong> → recherche étiologique (syndrome <span class=\"kw-etio\">génétique</span>, maladie osseuse)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td>\n              <ul>\n                <li>Morbidités périnatales : <span class=\"kw-alerte\">asphyxie</span>, <span class=\"kw-clinique\">hypothermie</span>, troubles métaboliques, polyglobulie, surmortalité</li>\n                <li>Complications endocrino-métaboliques à long terme</li>\n                <li><span class=\"kw-alerte\">Puberté précoce</span></li>\n                <li><span class=\"kw-alerte\">Syndrome métabolique</span> à l’âge adulte</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — Insuffisance surrénale chez l’adulte et l’enfant · 242 — <span class=\"kw-etio\">Hyperthyroïdie</span></em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/rickets","label":"Radiopaedia : Rickets (rachitisme carentiel)"}]},{"id":"53-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens radiologiques permettant de déterminer l’âge osseux","contenu":"<p>L’<span class=\"kw-def\">âge osseux (AO)</span> est un paramètre clé du bilan d’un retard statural : il oriente le <span class=\"kw-def\">pronostic</span> et le diagnostic différentiel (retard simple <em><span class=\"kw-bio\">vs</span></em> hypogonadisme, <em><span class=\"kw-bio\">vs</span></em> maladie osseuse).</p>\n\n      <h4>Technique de référence</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen</strong></td>\n            <td><span class=\"kw-imagerie\">Radiographie de la main gauche et du poignet de face</span></td>\n          </tr>\n          <tr>\n            <td><strong>Méthode</strong></td>\n            <td>Atlas de référence — <strong>méthode de Greulich et Pyle</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Repère clé : sésamoïde du pouce</strong></td>\n            <td>\n              <ul>\n                <li>Apparition <strong>contemporaine du démarrage pubertaire</strong></li>\n                <li>Fille : âge osseux <span class=\"kw-chiffre\">11 ans</span></li>\n                <li>Garçon : âge osseux <span class=\"kw-chiffre\">13 ans</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Intérêt diagnostique majeur.</strong> Un <span class=\"kw-clinique\">AO retardé</span> (apparition retardée du sésamoïde du pouce) chez un enfant petit + asymptomatique + taille &gt; – 2 DS + perte &lt; 1 DS → oriente vers un <strong>retard simple de croissance et de puberté</strong> (<span class=\"kw-def\">pronostic</span> statural satisfaisant).\n      </div>\n\n      <h4>Autres examens radiologiques utiles selon le contexte</h4>\n\n      <ul>\n        <li><span class=\"kw-imagerie\">RX du poignet et du genou</span> : recherche de signes de <span class=\"kw-clinique\">rachitisme carentiel</span> (<span class=\"kw-radio\">élargissement métaphysaire</span>, aspect en cupule « <span class=\"kw-radio\">toit de pagode</span> », <span class=\"kw-radio\">déminéralisation</span>)</li>\n        <li><span class=\"kw-imagerie\">RX osseuses ciblées (squelette)</span> : devant une <strong>petite taille disproportionnée</strong> → maladie osseuse constitutionnelle</li>\n        <li><span class=\"kw-imagerie\">IRM hypothalamo-hypophysaire</span> : devant cassure de la vitesse de croissance et/ou signes d’<span class=\"kw-alerte\">HTIC</span> → recherche d’un <strong>craniopharyngiome</strong> ou d’une autre tumeur</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 49 — Développement pubertaire normal et pathologique</em></p>","frequence":0}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie & CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Cassure de la vitesse de croissance <span class=\"q\">— et/ou signes d'<span class=\"kw-alerte\">HTIC</span></span></strong></p><p><span class=\"kw-imagerie\">imagerie cérébrale et hypophysaire</span> (<span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span>) sans délai + <span class=\"kw-clinique\">fond d'œil</span></p><ul><li>Éliminer en 1ᵉʳ lieu une <span class=\"kw-etio\">tumeur hypothalamo-hypophysaire</span> (<span class=\"kw-alerte\">craniopharyngiome</span>)</li><li><span class=\"kw-alerte\">HTIC</span> : <span class=\"kw-clinique\">œdème papillaire</span>, <span class=\"kw-clinique\">céphalées</span> · <span class=\"kw-clinique\">hémianopsie bitemporale</span> (compression du chiasma optique)</li><li>Évoquer un <span class=\"kw-alerte\">diabète insipide</span> souvent associé</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Cassure de la vitesse de croissance</span> → pathologie <span class=\"kw-etio\">acquise</span> (évoquer <span class=\"kw-alerte\">craniopharyngiome</span> en 1ᵉʳ lieu)</li><li><span class=\"kw-alerte\">Signes d'HTIC</span> : <span class=\"kw-clinique\">œdème papillaire</span> · <span class=\"kw-clinique\">hémianopsie bitemporale</span></li><li><span class=\"kw-alerte\">Prise de poids + ralentissement statural</span> → pathologie <span class=\"kw-etio\">hormonale</span> (<span class=\"kw-alerte\">déficit en GH</span>, <span class=\"kw-def\">hypothyroïdie</span>, <span class=\"kw-def\">hypercorticisme</span>) ou <span class=\"kw-etio\">génétique</span></li><li>Fille avec retard statural → évoquer systématiquement un <span class=\"kw-alerte\">syndrome de Turner</span> → <span class=\"kw-bio\">caryotype</span> sanguin</li><li><span class=\"kw-clinique\">Petite taille disproportionnée</span> → <span class=\"kw-etio\">maladie osseuse constitutionnelle</span> → <span class=\"kw-imagerie\">RX de squelette</span></li><li><span class=\"kw-alerte\">Insuffisance pondérale + avance staturale</span> → <span class=\"kw-def\">hyperthyroïdie</span> (signature paradoxale)</li><li><span class=\"kw-alerte\">Accidents hypoglycémiques</span> répétés et révélateurs → <span class=\"kw-alerte\">déficit en GH</span> (déficits somatotrope/corticotrope)</li></ul>","principes":"<p>Le <span class=\"kw-def\">retard staturo-pondéral</span> est <strong>toujours un signe d'appel</strong> justifiant une évaluation — jamais une simple <span class=\"kw-def\">surveillance</span> d'attente. La démarche s'oriente selon que le retard est <strong>pondéral prédominant</strong> ou <strong>statural prédominant</strong>.</p><p><strong>Retard pondéral isolé ou antérieur</strong></p><ul><li>Explorer un déséquilibre de la <span class=\"kw-clinique\">balance énergétique</span> : <span class=\"kw-etio\">carence d'apports</span>, <span class=\"kw-etio\">malabsorption</span> (<span class=\"kw-alerte\">maladie cœliaque</span>, <span class=\"kw-clinique\">MICI</span>, <span class=\"kw-clinique\">APLV</span>), <span class=\"kw-etio\">augmentation des dépenses</span>, <span class=\"kw-etio\">pertes excessives</span></li><li>Penser à l'<span class=\"kw-def\">hyperthyroïdie</span> si <span class=\"kw-clinique\">avance staturale</span> associée</li></ul><p><strong>Retard statural prédominant</strong></p><p>devant une <span class=\"kw-clinique\">petite taille disproportionnée</span> → <span class=\"kw-imagerie\">RX de squelette</span> + <span class=\"kw-bio\">analyses génétiques ciblées</span></p><ul><li>Bilan orienté : <span class=\"kw-bio\">TSH-T4L</span>, <span class=\"kw-bio\">IGF-1</span>, <span class=\"kw-bio\">cortisolurie des 24 h</span> si <span class=\"kw-clinique\">poids excessif</span> ; <span class=\"kw-imagerie\">RX osseuses</span> si <span class=\"kw-clinique\">disproportion</span> ; avis <span class=\"kw-etio\">génétique</span> si <span class=\"kw-clinique\">dysmorphie</span> / malformations / retard mental</li><li>Bilan général sans orientation : <span class=\"kw-bio\">NFS, ionogramme, créatinine, bilan hépatique, VS, CRP</span>, <span class=\"kw-bio\">calcémie/phosphatémie</span>, <span class=\"kw-bio\">IgA anti-transglutaminase + IgA totales</span>, <span class=\"kw-bio\">caryotype chez la fille</span></li></ul><p><strong>Carence de soins <span class=\"q\">— nanisme psychosocial</span></strong></p><p>diagnostic confirmé a posteriori par l'<span class=\"kw-clinique\">amélioration de la croissance après éloignement de l'enfant de sa famille</span></p><ul><li>Mécanisme : <span class=\"kw-etio\">carence de soins + négligence</span> → carence d'apports + déficit hormonal d'origine psychologique</li></ul><p><strong>Rachitisme carentiel</strong></p><ul><li>Apport de <span class=\"kw-ttt\">calcium</span> + <span class=\"kw-ttt\">vitamine D</span> (la prophylaxie par <span class=\"kw-ttt\">vitamine D</span> est systématique)</li><li>Normocalcémie : <span class=\"kw-ttt\">vitamine D</span> <span class=\"kw-chiffre\">200 000 UI</span> en dose de charge puis <span class=\"kw-chiffre\">2000–5000 UI/j</span></li><li>Hypocalcémie : <span class=\"kw-ci\">corriger la calcémie avant de supplémenter en vitamine D</span></li></ul><p><strong>Retard simple de croissance et de puberté</strong></p><ul><li><span class=\"kw-clinique\">Surveillance clinique simple</span> suffisante (examens complémentaires inutiles) si tous <span class=\"kw-clinique\">les</span> critères sont réunis</li><li>Suivre l'enfant jusqu'au <span class=\"kw-clinique\">démarrage de la puberté</span> — <span class=\"kw-def\">pronostic</span> statural et pubertaire bon</li></ul>","suivi":"<p><strong>Rythme des mesures <span class=\"q\">— carnet de santé</span></strong></p><ul><li>Naissance → <span class=\"kw-chiffre\">2 ans</span> : au minimum <span class=\"kw-chiffre\">tous les 3 mois</span></li><li><span class=\"kw-chiffre\">2 ans</span> → fin de croissance : <span class=\"kw-chiffre\">tous les 6 mois</span></li><li>Mesurer <span class=\"kw-clinique\">poids</span> + <span class=\"kw-clinique\">taille</span> ; ajouter le <span class=\"kw-clinique\">périmètre crânien</span> jusqu'à <span class=\"kw-chiffre\">3 ans</span></li></ul><p><strong>Petite taille de naissance (RCIU / PAG)</strong></p><ul><li>Normalisation de la taille dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 premières années</span> dans <span class=\"kw-chiffre\">90 %</span> des cas</li><li><span class=\"kw-alerte\">Pas de rattrapage dans 10–15 %</span> → recherche étiologique (<span class=\"kw-etio\">syndrome génétique</span>, <span class=\"kw-etio\">maladie osseuse</span>)</li><li>Risque ultérieur : <span class=\"kw-alerte\">puberté précoce</span> · <span class=\"kw-alerte\">syndrome métabolique</span> à l'âge adulte</li></ul><p><strong>Retard simple de croissance et de puberté</strong></p><ul><li><span class=\"kw-clinique\">Surveillance jusqu'au démarrage pubertaire</span> ; <span class=\"kw-def\">pronostic</span> bon</li><li>Réévaluer (sort du cadre du retard simple) si <span class=\"kw-alerte\">perte staturale &gt; 1 DS</span> ou apparition de signes d'alerte</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/croissance-developpement/chapitre-1-items-53-243-croissance-normale-pathologique","label":"Collège Pédiatrie — Croissance normale et pathologique (chap. 1, items 53/243)"},{"href":"https://www.pediaos.fr/croissance.html","label":"Pediaos.fr — Croissance"}],"cards":[{"i":"196fbf11c846","n":53,"o":"53-1","u":"Définition","t":"Connaître la définition de la croissance normale de l’enfant","q":"Quels sont les repères chiffrés clés de la croissance normale à la naissance et à 1 an ?","a":"<p>Voici les repères clés :</p><ul><li><strong>Naissance à terme</strong> : Taille à <strong>50 cm</strong>, Poids à <strong>3,5 kg</strong>, Périmètre Crânien à <strong>35 cm</strong>.</li><li><strong>1 an</strong> : Taille à <strong>75 cm</strong> (+25 cm depuis la naissance), Poids à <strong>10 kg</strong> (PN × 3), Périmètre Crânien à <strong>47,5 cm</strong>.</li></ul>"},{"i":"1a07fb734a7b","n":53,"o":"53-1","u":"Définition","t":"Connaître la définition de la croissance normale de l’enfant","q":"Quelles sont les quatre phases de la croissance staturale de l'enfant ?","a":"<p>Les quatre phases de la croissance staturale sont :</p><ul><li>La <strong>croissance fœtale</strong> : la phase la plus rapide, reflétée par les paramètres de naissance (ex : 50 cm en 9 mois).</li><li>La phase de <strong>naissance à 4 ans</strong> : vitesse élevée décroissante, avec mise sur le couloir de croissance génétique (ex : +25 cm la première année, puis +10 cm/an entre 2 et 3 ans).</li><li>La phase de <strong>croissance linéaire</strong> (de 4 ans au début puberté) : vitesse de <strong>5-6 cm/an</strong> (seuil pathologique &lt; 4 cm/an après 4 ans).</li><li>La phase de la <strong>puberté</strong> : accélération de la vitesse (pic de croissance pubertaire), avec un gain de <strong>+20-25 cm</strong> chez la fille et <strong>+25-30 cm</strong> chez le garçon.</li></ul>"},{"i":"3d264ebbbb6a","n":53,"o":"53-1","u":"Définition","t":"Connaître la définition de la croissance normale de l’enfant","q":"Quels sont les facteurs principaux qui influencent la croissance de l'enfant ?","a":"<p>La croissance est le résultat d'une intégration complexe de facteurs :</p><ul><li><strong>Nutritionnels</strong></li><li><strong>Psychoaffectifs</strong></li><li><strong>Osseux</strong></li><li><strong>Génétiques</strong> (définissant la taille cible)</li><li><strong>Hormonaux</strong> (notamment la <strong>GH</strong>, l'<strong>IGF-1</strong>, les <strong>hormones thyroïdiennes</strong> et les <strong>hormones sexuelles</strong>)</li></ul>"},{"i":"0f39ec5c0879","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Quels sont les critères diagnostiques d'une anomalie de croissance staturale ?","a":"<ul><li>Une taille <strong>inférieure à &ndash;2 DS</strong> (déviations standard) selon les courbes de la population générale, et/ou</li><li>Une taille <strong>inférieure à &ndash;1,5 DS</strong> par rapport à la taille cible génétique, et/ou</li><li>Un <strong>ralentissement ou une cassure de la vitesse de croissance</strong> (inférieure à <strong>4 cm/an</strong> après l'âge de 4 ans).</li></ul>"},{"i":"514be81eb0c5","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Quel diagnostic doit être systématiquement évoqué devant un retard statural chez une fille ?","a":"<p>Devant un retard statural chez une fille, il faut systématiquement évoquer un <strong>syndrome de Turner</strong> et réaliser un <strong>caryotype sanguin</strong> pour confirmation.</p>"},{"i":"543c475686ab","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Quelles sont les principales pistes étiologiques en cas de retard statural prédominant chez l'enfant ?","a":"<p>En cas de retard statural prédominant (avec un poids en rapport avec la taille ou excessif), les principales pistes sont :</p><ul><li>Une origine <strong>énergétique</strong>.</li><li>Une origine <strong>endocrinienne</strong> (comme une <strong>hypothyroïdie</strong>, un <strong>hypercorticisme</strong> ou un <strong>déficit en GH</strong>).</li><li>Une origine <strong>osseuse ou génétique</strong> (il faut toujours évoquer le <strong>syndrome de Turner</strong> chez la fille, justifiant un <strong>caryotype systématique</strong>).</li></ul>"},{"i":"69b6b98ea840","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Comment définit-on un retard de croissance staturo-pondérale chez l'enfant ?","a":"<p>Un retard de croissance staturo-pondérale est défini par une anomalie de la taille et/ou un ralentissement de la vitesse de croissance, nécessitant toujours une évaluation.</p>"},{"i":"729f25f6b482","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Quels sont les signes d'alerte indiquant une urgence diagnostique face à un retard de croissance staturo-pondérale ?","a":"<p>Une urgence diagnostique doit être évoquée devant une <strong>cassure de la vitesse de croissance</strong> et/ou des <strong>signes d'hypertension intracrânienne (HTIC)</strong>, afin d'éliminer en premier lieu une <strong>pathologie tumorale hypophysaire</strong> (notamment un <strong>craniopharyngiome</strong>). Des examens en urgence sont nécessaires : <strong>imagerie cérébrale et hypophysaire</strong> (TDM ou IRM) et un <strong>fond d'œil</strong>.</p>"},{"i":"744686a8a1c6","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire dans l'enquête clinique d'un retard de croissance staturo-pondérale ?","a":"<p>L'interrogatoire doit rechercher systématiquement :</p><ul><li>Les <strong>antécédents familiaux</strong> (consanguinité, arbre généalogique détaillé avec poids, tailles, âges pubertaires des parents et fratrie).</li><li>Les <strong>antécédents personnels</strong> (déroulement et terme de la grossesse, mensurations à la naissance, pathologie néonatale, acquisitions psychomotrices, alimentation, antécédents médico-chirurgicaux, traitements).</li><li>Le <strong>contexte psychosocial</strong> et le <strong>retentissement psychologique</strong>.</li><li>En période pubertaire, la <strong>classification de Tanner</strong> des caractères sexuels secondaires.</li></ul>"},{"i":"fc72cf4f9dd9","n":53,"o":"53-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un retard de croissance staturo-pondérale","q":"Quelle démarche étiologique doit être adoptée face à un retard pondéral isolé ou antérieur au retard statural ?","a":"<p>Devant un retard pondéral isolé ou précédant le retard statural, l'orientation étiologique principale est un <strong>déséquilibre de la balance énergétique</strong>, qui peut être dû à :</p><ul><li>Une <strong>carence d'apports</strong>.</li><li>Une <strong>malabsorption</strong>.</li><li>Une <strong>augmentation des dépenses énergétiques</strong>.</li><li>Des <strong>pertes excessives</strong>.</li></ul>"}]};